import {makeAttachment,validateAttachments} from './attachments.mjs';
import {alphaBounds,imageRect,previewAnchor,fitGlasses} from './accessory-image.mjs';
import {fitLibraryGlasses,glassesTemplePoint} from './glasses-fit.mjs';
import {mountHeadFitting} from './head-fit-ui.mjs';
import {resolveStockHat,restoreLibraryHat} from './stock-hats.mjs';
import {activateEquipment,normalizeEquipment,equipmentType} from './equipment.mjs';
import {accessoryName,attachmentName,CATEGORY_NAMES,searchNames} from './names-vi.mjs';
const el=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e};
const options=(select,rows)=>{select.replaceChildren(...rows.map(([value,text])=>{const o=new Option(text,value);o.title=value;return o}));if(rows.length)select.selectedIndex=0};
export function mountAccessories(actions){
 const panel=el('section');panel.className='accessory-panel';panel.id='accessoryPanel';
 panel.innerHTML=`<h2>PHỤ KIỆN & VŨ KHÍ</h2><p id="accessorySummary"></p><input id="accessorySearch" placeholder="Tìm: headphones, hat, spear, sword…" aria-label="Tìm phụ kiện"><label>Loại<select id="accessoryCategory"><option value="hat">Mũ / tai nghe</option><option value="weapon">Vũ khí</option><option value="glasses">Kính</option></select></label><select id="accessoryCatalog" size="5" aria-label="Phụ kiện có sẵn"></select><button id="addAccessory">＋ Gắn món có sẵn</button><button id="uploadAccessory">＋ Tải ảnh phụ kiện riêng</button><input id="accessoryFile" type="file" accept="image/png,image/webp" hidden><h3>Đang gắn trên nhân vật</h3><select id="attachmentList" size="3" aria-label="Phụ kiện đang gắn"></select><div id="accessorySettings"><label><input id="attachmentVisible" type="checkbox"> Hiện phụ kiện</label><label><input id="dragAccessory" type="checkbox"> Kéo phụ kiện đang chọn trên nhân vật</label><div class="pair"><label>Điểm gắn<select id="attachmentSocket"><option value="head">Đỉnh đầu</option><option value="face">Mặt / tai</option><option value="handF">Bàn tay gần</option><option value="handB">Bàn tay xa</option></select></label><label>Lớp vẽ<select id="attachmentLayer"><option value="front">Trước đầu / tay</option><option value="back">Sau đầu / tay</option></select></label></div><div class="pair"><label>Lệch X<input id="attachmentX" type="number" step="0.5"></label><label>Lệch Y<input id="attachmentY" type="number" step="0.5"></label></div><div class="pair"><label>Rộng<input id="attachmentW" type="number" min="1" max="2000" step="1"></label><label>Cao<input id="attachmentH" type="number" min="1" max="2000" step="1"></label></div><div class="pair"><label>Tỷ lệ<input id="attachmentScale" type="number" min="0.05" max="10" step="0.05"></label><label>Góc (độ)<input id="attachmentRotation" type="number" step="1"></label></div><canvas id="attachmentPreview" width="250" height="190"></canvas><div class="pair"><label>Neo X (0–1)<input id="attachmentAX" type="number" min="0" max="1" step="0.01"></label><label>Neo Y (0–1)<input id="attachmentAY" type="number" min="0" max="1" step="0.01"></label></div><p>Bấm trên ảnh để đặt vành mũ / điểm cầm. Khi đổi pose, phụ kiện đi theo đầu hoặc tay. Tai nghe có thể gắn Đỉnh đầu rồi chỉnh lệch Y.</p><button id="removeAccessory">Tháo món đang chọn</button></div>`;
 document.querySelector('.library').append(panel);
 panel.querySelector('#accessorySearch').placeholder='Tìm mũ, kính, kiếm, tai nghe…';
 panel.querySelector('#attachmentList').insertAdjacentHTML('beforebegin','<p>Chọn một món để dùng. Món cùng loại sẽ tự ẩn nhưng vẫn giữ trong danh sách và giữ nguyên các chỉnh sửa.</p>');
 const shortcut=el('button','♧ Phụ kiện');shortcut.id='jumpAccessories';shortcut.onclick=()=>panel.scrollIntoView({block:'start',behavior:'smooth'});document.querySelector('header nav').prepend(shortcut);
 const $=id=>panel.querySelector('#'+id);let catalog=[],selected=null,previewRect=null,previewVersion=0,previewImage=null,drag=null;
 $('attachmentSocket').add(new Option('Lưng / cánh','back'));
 $('attachmentList').insertAdjacentHTML('afterend','<button id="editWingRig" hidden>✧ Thiết kế xương & animation cánh</button>');
 $('editWingRig').onclick=()=>document.getElementById('wingStudioButton').click();
 $('attachmentList').insertAdjacentHTML('afterend','<button id="restoreGlassesSizes" hidden>◎ Căn cỡ kính theo mắt & tai</button><p id="glassesSizeInfo" hidden>Cân đối tròng theo mắt; mẫu có mốc quai sẽ móc quai vào tai gần. Không lấy bề rộng tóc làm cỡ kính. Chỉ đặt lại kính đang chọn, có thể Hoàn tác. Ảnh kính riêng chưa có mốc tròng giữ nguyên cỡ đã chỉnh.</p>');
 $('attachmentList').insertAdjacentHTML('afterend','<button id="restoreLibraryHat" hidden>↶ Khôi phục cỡ & neo mũ thư viện</button><p id="restoreLibraryHatInfo" hidden>Chỉ đặt lại cỡ, tỷ lệ, góc và điểm neo của mũ đang chọn theo dữ liệu game gốc, thay các chỉnh tay của mũ đó. Kính / món khác giữ nguyên. Có thể Hoàn tác.</p>');
 $('attachmentPreview').insertAdjacentHTML('beforebegin','<button id="fitGlasses">◎ Căn kính vào mắt · giữ nguyên cỡ</button><p id="fitGlassesInfo">Chọn loại Kính trước khi tải ảnh. Điểm neo trên kính sẽ trùng điểm gắn trên mặt; dùng Lệch X/Y hoặc bật kéo phụ kiện để căn thêm. Căn neo không đổi Rộng/Cao, Tỷ lệ hoặc Góc.</p>');
 $('attachmentPreview').insertAdjacentHTML('afterend','<p>Kéo dấu cộng lên cầu kính (giữa hai tròng). Ảnh mới được bỏ viền trong suốt tự động; ảnh đã lưu giữ nguyên dữ liệu.</p>');
 $('attachmentSocket').options[1].text='Mắt / cầu kính';
 const list=()=>actions.project()?.attachments||[];
 const current=()=>list().find(a=>a.id===selected);
 const safe=fn=>async e=>{try{await fn(e)}catch(error){actions.message('Lỗi phụ kiện: '+error.message)}};
 const hatFitting=mountHeadFitting({container:panel,current,items:list,head:actions.head,image:actions.image,category:()=>$('accessoryCategory').value,mutate,message:actions.message});
 function imageBounds(img){if(img.naturalWidth*img.naturalHeight>16777216)throw Error('Ảnh quá lớn; hãy thu nhỏ xuống tối đa 16 triệu pixel');const canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;canvas.getContext('2d').drawImage(img,0,0);return {canvas,bounds:alphaBounds(canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height)}}
 function drawPreview(anchor=current()?.anchor){if(!previewImage||!anchor)return;const canvas=$('attachmentPreview'),ctx=canvas.getContext('2d'),{x,y,w,h}=previewRect;ctx.clearRect(0,0,250,190);ctx.drawImage(previewImage,x,y,w,h);ctx.strokeStyle='#e5f9a9';ctx.lineWidth=2;const px=x+anchor[0]*w,py=y+anchor[1]*h;ctx.beginPath();ctx.arc(px,py,6,0,7);ctx.moveTo(px-10,py);ctx.lineTo(px+10,py);ctx.moveTo(px,py-10);ctx.lineTo(px,py+10);ctx.stroke()}
 async function mutate(fn){const items=structuredClone(list());fn(items);const next=normalizeEquipment(items,catalog);validateAttachments(next);await actions.set(next);await refresh()}
 const replace=(items,next)=>items.splice(0,items.length,...next);
 async function use(id){selected=id;const next=activateEquipment(list(),id,catalog);if(JSON.stringify(next)===JSON.stringify(list()))await refresh();else await mutate(items=>replace(items,next))}
 function library(){const q=$('accessorySearch').value.trim(),type=$('accessoryCategory').value;options($('accessoryCatalog'),catalog.filter(a=>a.category===type&&searchNames(q,accessoryName(a),a.name,a.originalName,a.id)).map(a=>[a.id,accessoryName(a)]));if(actions.project())hatFitting.refresh().catch(error=>actions.message(error.message))}
 async function refresh(){options($('attachmentList'),list().map((a,i)=>[a.id,(a.visible===false?'○ ':'● ')+attachmentName(a,catalog,i)]));if(!current())selected=list().find(a=>a.visible!==false)?.id||list()[0]?.id||null;$('attachmentList').value=selected||'';const a=current();$('accessorySettings').hidden=!a;$('editWingRig').hidden=!a?.wingRig;const stockHat=a?.socket==='head'&&!a.wingRig&&catalog.some(e=>e.id===a.sourceId&&e.category==='hat');$('restoreLibraryHat').hidden=$('restoreLibraryHatInfo').hidden=!stockHat;const stockGlasses=a&&!a.wingRig&&catalog.some(e=>e.id===a.sourceId&&e.category==='glasses'&&e.sprite.lens);$('restoreGlassesSizes').hidden=$('glassesSizeInfo').hidden=!stockGlasses;if(!a){await hatFitting.refresh();return}
  // Native iOS selects do not emit change when selecting the same value.
  // A disabled prompt lets an explicitly hidden selection be chosen again.
  if(a.visible===false){const prompt=new Option('○ '+attachmentName(a,catalog)+' · đang ẩn, chọn để dùng','');prompt.disabled=true;$('attachmentList').prepend(prompt);$('attachmentList').value=''}
  $('attachmentVisible').checked=a.visible!==false;$('attachmentSocket').value=a.socket;$('attachmentLayer').value=a.layer;
  const wing=!!a.wingRig;$('editWingRig').hidden=!wing;$('attachmentSocket').disabled=$('attachmentLayer').disabled=wing;
  for(const id of ['attachmentW','attachmentAX'])$(id).closest('.pair').hidden=wing;
  $('attachmentPreview').hidden=wing;$('fitGlasses').hidden=$('fitGlassesInfo').hidden=wing||!!stockGlasses;
  for(const [field,key]of [['X','x'],['Y','y'],['W','w'],['H','h'],['Scale','scale']])$('attachment'+field).value=Number(a[key].toFixed(3));
  $('attachmentRotation').value=Number((a.rotation*180/Math.PI).toFixed(2));$('attachmentAX').value=a.anchor[0];$('attachmentAY').value=a.anchor[1];
  previewRect=null;previewImage=null;const version=++previewVersion;if(wing){await hatFitting.refresh();return}const img=await actions.image(a.src);if(version!==previewVersion||current()?.id!==a.id)return;previewImage=img;previewRect=imageRect(img.naturalWidth,img.naturalHeight);drawPreview();await hatFitting.refresh();
 }
 $('accessorySearch').oninput=library;$('accessoryCategory').onchange=library;$('attachmentList').onchange=safe(async()=>{await use($('attachmentList').value);actions.message('Đang dùng '+attachmentName(current(),catalog)+'. Món cùng loại đã ẩn, không bị xóa.');});
 $('addAccessory').onclick=safe(async()=>{if(!actions.project())return;const entry=catalog.find(a=>a.id===$('accessoryCatalog').value);if(!entry)throw Error('Chọn một món trong thư viện');const existing=list().find(a=>a.sourceId===entry.id&&equipmentType(a,catalog)===entry.category);if(existing){await use(existing.id);actions.message('Đang dùng lại '+accessoryName(entry)+'; giữ nguyên các chỉnh sửa.');return}let a=makeAttachment({...entry,name:accessoryName(entry)},actions.headWidth());a.category=entry.category;if(entry.category==='glasses')a=fitLibraryGlasses(a,entry,actions.head(),actions.eyes?.());await actions.image(a.src);selected=a.id;await mutate(items=>items.push(a));actions.message('Đã gắn '+a.name+(entry.category==='glasses'?(glassesTemplePoint(entry)?' theo mắt và quai móc tai.':' theo hai mốc mắt.'):'. Có thể chỉnh điểm neo và độ lệch.'))});
 $('uploadAccessory').onclick=()=>$('accessoryFile').click();$('accessoryFile').onchange=safe(async()=>{
  const file=$('accessoryFile').files[0];if(!file)return;const project=actions.project(),category=$('accessoryCategory').value;
  try{if(!['image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Ảnh PNG/WebP tối đa 8 MB');
   const raw=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)}),img=await actions.image(raw),{canvas,bounds}=imageBounds(img),cropped=document.createElement('canvas');cropped.width=bounds.w;cropped.height=bounds.h;cropped.getContext('2d').drawImage(canvas,bounds.x,bounds.y,bounds.w,bounds.h,0,0,bounds.w,bounds.h);
   let number=1;while(list().some(a=>a.name===(CATEGORY_NAMES[category]+' tải lên '+number)))number++;
   const src=cropped.toDataURL('image/png'),width=category==='weapon'?Math.min(160,bounds.w):actions.headWidth()*1.2,entry={id:file.name,name:CATEGORY_NAMES[category]+' tải lên '+number,category,fit:1.2,grip:.2,sprite:{src,w:width,h:width*bounds.h/bounds.w,ax:.5,brim:.8}};let a=makeAttachment(entry,actions.headWidth()),notice='';a.category=category;
   if(category==='hat'){const result=await hatFitting.fitUpload(a);a=result.attachment;notice=result.notice||''}
   if(actions.project()!==project)throw Error('Project vừa thay đổi; hãy tải ảnh lại');selected=a.id;await mutate(items=>items.push(a));actions.message(notice||'Đã tải ảnh, bỏ viền trong suốt và gắn vào '+(category==='glasses'?'mắt. Kéo điểm neo tới cầu kính nếu cần.':category==='weapon'?'tay.':'đầu. Nếu là kính, bấm Căn kính vào mắt.'));
  }finally{$('accessoryFile').value=''}
 });
 $('fitGlasses').onclick=safe(async()=>{const a=current();if(!a)return;const img=await actions.image(a.src),{bounds}=imageBounds(img);await mutate(items=>fitGlasses(items.find(item=>item.id===a.id),bounds,img.naturalWidth,img.naturalHeight));actions.message('Đã căn kính vào mắt; giữ nguyên kích thước, tỷ lệ và góc. Kéo dấu cộng tới cầu kính để tinh chỉnh.')});
 $('restoreLibraryHat').onclick=safe(async()=>{
  const a=current(),entry=catalog.find(e=>e.id===a?.sourceId&&e.category==='hat');
  const restored=restoreLibraryHat(a,entry,actions.headWidth());
  await mutate(items=>{const i=items.findIndex(item=>item.id===a.id);if(i<0)throw Error('Mũ đang chọn vừa thay đổi');items[i]=restored});
  actions.message('Đã khôi phục cỡ và neo chuẩn của mũ thư viện; kính / món khác giữ nguyên. Có thể Hoàn tác.');
 });
 $('restoreGlassesSizes').onclick=safe(async()=>{const a=current(),entry=catalog.find(e=>e.id===a?.sourceId&&e.category==='glasses');const fixed=fitLibraryGlasses(a,entry,actions.head(),actions.eyes?.());await mutate(items=>{const i=items.findIndex(item=>item.id===a.id);if(i<0)throw Error('Kính vừa thay đổi');items[i]=fixed});actions.message('Đã căn cỡ kính theo mắt'+(glassesTemplePoint(entry)?' và quai móc tai':'')+'; mũ, trang phục và món khác giữ nguyên. Có thể Hoàn tác.');});
 for(const [field,key]of [['X','x'],['Y','y'],['W','w'],['H','h'],['Scale','scale'],['Rotation','rotation']])$('attachment'+field).onchange=safe(()=>{const value=$('attachment'+field).valueAsNumber;return mutate(items=>{items.find(a=>a.id===selected)[key]=field==='Rotation'?value*Math.PI/180:value})});
 for(const [id,key]of [['attachmentSocket','socket'],['attachmentLayer','layer']])$(id).onchange=safe(()=>mutate(items=>items.find(a=>a.id===selected)[key]=$(id).value));
 $('attachmentVisible').onchange=safe(()=>mutate(items=>{if($('attachmentVisible').checked)replace(items,activateEquipment(items,selected,catalog));else items.find(a=>a.id===selected).visible=false}));
 for(const [id,index]of [['attachmentAX',0],['attachmentAY',1]])$(id).onchange=safe(()=>mutate(items=>items.find(a=>a.id===selected).anchor[index]=$(id).valueAsNumber));
 const preview=$('attachmentPreview');
 function moveAnchor(e){if(!drag||drag.pointer!==e.pointerId)return;e.preventDefault();drag.anchor=previewAnchor(e.clientX,e.clientY,preview.getBoundingClientRect(),drag.rect);drawPreview(drag.anchor);$('attachmentAX').value=drag.anchor[0];$('attachmentAY').value=drag.anchor[1];actions.previewAnchor?.(drag.id,drag.anchor)}
 preview.onpointerdown=e=>{if(!current()||!previewRect||drag)return;drag={id:current().id,pointer:e.pointerId,rect:{...previewRect},original:[...current().anchor]};preview.setPointerCapture(e.pointerId);moveAnchor(e)};
 preview.onpointermove=moveAnchor;
 preview.onpointerup=safe(async e=>{if(!drag||drag.pointer!==e.pointerId)return;moveAnchor(e);const edit=drag;drag=null;preview.releasePointerCapture(e.pointerId);try{await mutate(items=>{const a=items.find(a=>a.id===edit.id);if(a)a.anchor=edit.anchor})}catch(error){actions.previewAnchor?.(edit.id,edit.original);throw error}});
 preview.onpointercancel=preview.onlostpointercapture=()=>{if(!drag)return;actions.previewAnchor?.(drag.id,drag.original);drag=null;drawPreview();const a=current();if(a){$('attachmentAX').value=a.anchor[0];$('attachmentAY').value=a.anchor[1]}};
 preview.oncontextmenu=e=>e.preventDefault();
 $('removeAccessory').onclick=safe(()=>mutate(items=>{items.splice(items.findIndex(a=>a.id===selected),1)}));
 return {refresh,selected:current,dragEnabled:()=>$('dragAccessory').checked&&!!current(),updatePosition:()=>{const a=current();if(a){$('attachmentX').value=a.x.toFixed(2);$('attachmentY').value=a.y.toFixed(2)}},setCatalog(entries,build){catalog=(entries||[]).map(e=>resolveStockHat(e,build));const counts={};for(const e of catalog)counts[e.category]=(counts[e.category]||0)+1;$('accessorySummary').textContent=`${counts.hat||0} mũ/tai nghe · ${counts.weapon||0} vũ khí · ${counts.glasses||0} kính`;library()}};
}
